    tags: ["अष्टावक्र गीता 18.19","भावाभावविहीनो यः","नैव किञ्चित्कृतं तेन","bhāvābhāvavihīno","actionless while active","ashtavakra 18.19"],
    rel: [["18.18","वर्तमानोऽपि लोकवत्।"],["18.20","प्रवृत्तौ वा निवृत्तौ वा।"]],
